style.css:
@-moz-document domain("roblox.com") {
:root {
        --background-primary: rgba(20, 60, 80, 0.45) !important;
        --background-secondary: rgba(10, 30, 40, 0.7) !important;
        --bg-container: rgba(20, 60, 80, 0.4) !important;
        --button-primary-bg: rgba(0, 130, 150, 0.8) !important;
    }
    body, html, #container-main, .container-main, .content {
        background-image: url("https://ibb.co") !important;
        background-color: transparent !important;
        background-attachment: fixed !important;
        background-size: cover !important;
        background-position: center !important;
        background-repeat: no-repeat !important;
    }
    .game-card, .game-card-container, .game-card-link, .section-content, .item-card-container {
        background: rgba(20, 60, 80, 0.4) !important;
        background-color: rgba(20, 60, 80, 0.4) !important;
        border: 1px solid rgba(0, 180, 200, 0.3) !important;
        border-radius: 12px !important;
    }
    button, .btn-primary-md, .play-button, .btn-common-play-game {
        background-color: rgba(0, 130, 150, 0.8) !important;
        background: rgba(0, 130, 150, 0.8) !important;
        border-color: rgba(0, 180, 200, 1) !important;
        color: #ffffff !important;
    }
}
